import FeatureSectionV9 from "./components/feature-section-v9"

export default function Page() {
  return (
    <div className="p-4">
      <FeatureSectionV9 />
    </div>
  )
}

import { featureSectionItems } from "../lib/features"
import FeatureCard from "./feature-card"

import "../styles/feature-grid.css"

export default function FeatureGrid() {
  return (
    <ul className="m-0 grid list-none grid-cols-1 gap-8 p-0 sm:grid-cols-2 sm:gap-6 lg:grid-cols-4 lg:gap-7">
      {featureSectionItems.map((item) => (
        <li key={item.id} className="flex min-w-0">
          <FeatureCard item={item} />
        </li>
      ))}
    </ul>
  )
}

"use client"

import {
  Handshake,
  MagnifyingGlass,
  PencilSimple,
  ShieldCheck,
  type IconProps,
} from "@phosphor-icons/react"
import type { ComponentType } from "react"

import type { FeatureIconId } from "../lib/features"

const FEATURE_ICONS: Record<FeatureIconId, ComponentType<IconProps>> = {
  "magnifying-glass": MagnifyingGlass,
  pencil: PencilSimple,
  handshake: Handshake,
  shield: ShieldCheck,
}

export function FeatureIcon({
  icon,
  className,
}: {
  icon: FeatureIconId
  className?: string
}) {
  const Icon = FEATURE_ICONS[icon]

  return (
    <Icon
      aria-hidden
      className={className}
      weight="regular"
    />
  )
}

"use client"

import { useLayoutEffect, useRef, useState } from "react"
import { GrainGradient } from "@paper-design/shaders-react"

import type { GrainShaderTheme } from "../lib/features"

type ShaderViewport = {
  width: number
  height: number
  dpr: number
  ready: boolean
}

const initialViewport: ShaderViewport = { width: 0, height: 0, dpr: 1, ready: false }

const DESIGN_FALLBACK = { width: 992, height: 460 } as const

function adaptShader(theme: GrainShaderTheme, viewport: ShaderViewport) {
  const designWidth = theme.designWidth ?? DESIGN_FALLBACK.width
  const designHeight = theme.designHeight ?? DESIGN_FALLBACK.height

  const width = Math.max(1, Math.round(viewport.width * viewport.dpr))
  const height = Math.max(1, Math.round(viewport.height * viewport.dpr))

  const sizeRatio = Math.min(viewport.width / designWidth, viewport.height / designHeight)

  const { designWidth: _dw, designHeight: _dh, scale, ...shader } = theme

  return { ...shader, width, height, ...(scale !== undefined ? { scale: scale * sizeRatio } : {}) }
}

export function FeatureSectionV9ShaderBg(theme: GrainShaderTheme) {
  const ref = useRef<HTMLDivElement>(null)
  const [viewport, setViewport] = useState<ShaderViewport>(initialViewport)

  useLayoutEffect(() => {
    const el = ref.current
    if (!el) return

    const update = () => {
      const { width, height } = el.getBoundingClientRect()
      if (width < 1 || height < 1) return
      setViewport({ width, height, dpr: Math.min(window.devicePixelRatio || 1, 2), ready: true })
    }

    update()
    const observer = new ResizeObserver(update)
    observer.observe(el)
    return () => observer.disconnect()
  }, [])

  const renderProps = viewport.ready ? adaptShader(theme, viewport) : null

  return (
    <div
      ref={ref}
      className="fsv9-shader-frame"
      style={{ backgroundColor: theme.colorBack }}
      aria-hidden
    >
      {renderProps ? (
        <GrainGradient
          className="fsv9-shader-canvas"
          colors={[...renderProps.colors]}
          colorBack={renderProps.colorBack}
          fit="cover"
          height={renderProps.height}
          intensity={renderProps.intensity}
          noise={renderProps.noise}
          {...(renderProps.scale !== undefined ? { scale: renderProps.scale } : {})}
          shape={renderProps.shape}
          softness={renderProps.softness}
          speed={renderProps.speed}
          width={renderProps.width}
        />
      ) : null}
    </div>
  )
}

.fsv9-shader-frame {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.fsv9-shader-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  min-width: 100%;
  min-height: 100%;
}

.fsv9-shader-frame canvas {
  display: block;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover;
}

@media (prefers-reduced-motion: reduce) {
  .fsv9-shader-frame {
    display: none;
  }
}
